def words(text):
    """Yield (word, start) for each run of letters, skipping spaces."""
    pos = 0
    while pos < len(text):
        if text[pos] == " ":
            pos += 1
        elif text[pos].isalpha():
            start = pos
            while pos < len(text) and text[pos].isalpha():
                pos += 1
            yield (text[start:pos], start)
        else:
            raise ValueError(f"unexpected {text[pos]!r} at {pos}")

gen = words("let x ?")
print(next(gen))
